-- Remaining first-class records in the BuildLens operational chain. This migration is additive.
create table public.employee_reporting_relationships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), employee_id uuid not null references public.employees(id), manager_employee_id uuid not null references public.employees(id), effective_from date not null default current_date, effective_to date, check(employee_id <> manager_employee_id));
create table public.task_templates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), work_section_id uuid references public.work_sections(id), name text not null, definition jsonb not null default '{}'::jsonb, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.vendor_contacts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), vendor_id uuid not null references public.vendors(id), name text not null, email text, phone text, designation text, active boolean not null default true);
create table public.vendor_projects (vendor_id uuid references public.vendors(id), project_id uuid references public.projects(id), organization_id uuid not null references public.organizations(id), primary key(vendor_id,project_id));
create table public.vendor_villas (vendor_id uuid references public.vendors(id), villa_id uuid references public.villas(id), organization_id uuid not null references public.organizations(id), primary key(vendor_id,villa_id));
create table public.vendor_work_assignments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), vendor_id uuid not null references public.vendors(id), task_id uuid references public.tasks(id), work_section_id uuid references public.work_sections(id), assigned_at timestamptz not null default now());
create table public.vendor_contracts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), vendor_id uuid not null references public.vendors(id), project_id uuid references public.projects(id), contract_number text not null, effective_from date, effective_to date, status text not null default 'DRAFT', document_attachment_id uuid references public.attachments(id), unique(organization_id,contract_number));
create table public.vendor_performance (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), vendor_id uuid not null references public.vendors(id), measured_on date not null, on_time_score numeric(5,2) check(on_time_score between 0 and 100), quality_score numeric(5,2) check(quality_score between 0 and 100), notes text, unique(vendor_id,measured_on));
create table public.products (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, sku text, category text, unit text not null, active boolean not null default true, unique(organization_id,sku));
create table public.materials (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), product_id uuid not null references public.products(id), project_id uuid references public.projects(id), quantity_on_hand numeric(14,2) not null default 0 check(quantity_on_hand >= 0), reorder_level numeric(14,2) check(reorder_level >= 0), unit_cost numeric(14,2) check(unit_cost >= 0), updated_at timestamptz not null default now(), unique(product_id,project_id));
create table public.suppliers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), company_name text not null, contact_name text, phone text, email text, status text not null default 'ACTIVE', unique(organization_id,company_name));
create table public.purchase_orders (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), supplier_id uuid not null references public.suppliers(id), project_id uuid references public.projects(id), po_number text not null, status text not null default 'DRAFT', ordered_at timestamptz, expected_at date, total_amount numeric(14,2) check(total_amount >= 0), unique(organization_id,po_number));
create table public.material_deliveries (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), purchase_order_id uuid references public.purchase_orders(id), product_id uuid not null references public.products(id), delivered_at timestamptz not null default now(), quantity numeric(14,2) not null check(quantity > 0), accepted_by uuid references public.employees(id), evidence_attachment_id uuid references public.attachments(id));
create table public.material_allocations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), material_id uuid not null references public.materials(id), villa_id uuid references public.villas(id), task_id uuid references public.tasks(id), quantity numeric(14,2) not null check(quantity > 0), allocated_at timestamptz not null default now());
create table public.material_usage (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), material_id uuid not null references public.materials(id), task_id uuid references public.tasks(id), quantity numeric(14,2) not null check(quantity > 0), used_at timestamptz not null default now(), recorded_by uuid references auth.users(id));
create table public.villa_documents (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), project_id uuid not null references public.projects(id), attachment_id uuid not null references public.attachments(id), document_type text not null, version text not null, revision text, approval_status text not null default 'PENDING', effective_date date, superseded_at timestamptz, uploaded_by uuid references auth.users(id), uploaded_at timestamptz not null default now(), unique(villa_id,document_type,version,revision));
create table public.plan_versions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_document_id uuid not null references public.villa_documents(id), version text not null, effective_date date, superseded_at timestamptz, created_at timestamptz not null default now());
create table public.drawing_revisions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), plan_version_id uuid not null references public.plan_versions(id), revision text not null, notes text, issued_at timestamptz not null default now());
create table public.inspection_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), inspection_id uuid not null references public.inspections(id), label text not null, status text not null default 'PENDING', notes text);
create table public.quality_issues (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid references public.villas(id), task_id uuid references public.tasks(id), severity text not null default 'MEDIUM', status text not null default 'OPEN', description text not null, reported_at timestamptz not null default now(), resolved_at timestamptz, reported_by uuid references auth.users(id));
create table public.snags (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), quality_issue_id uuid references public.quality_issues(id), status text not null default 'OPEN', description text not null, due_at timestamptz, closed_at timestamptz);
create table public.notifications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), user_id uuid not null references auth.users(id), type text not null, title text not null, body text, entity_type text, entity_id uuid, read_at timestamptz, created_at timestamptz not null default now());

do $$ declare t text; begin foreach t in array array['employee_reporting_relationships','task_templates','vendor_contacts','vendor_projects','vendor_villas','vendor_work_assignments','vendor_contracts','vendor_performance','products','materials','suppliers','purchase_orders','material_deliveries','material_allocations','material_usage','villa_documents','plan_versions','drawing_revisions','inspection_items','quality_issues','snags','notifications'] loop execute format('alter table public.%I enable row level security', t); execute format('create policy %I on public.%I for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id))', t || '_tenant_access', t); end loop; end $$;
create index notifications_user_idx on public.notifications(organization_id,user_id,read_at,created_at desc);
create index material_deliveries_product_idx on public.material_deliveries(product_id,delivered_at desc);
